import json, subprocess, sys, hashlib
from pathlib import Path
rows=json.loads(Path('inputs/intake.json').read_text(encoding='utf-8'))
before={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in Path('inputs').iterdir() if p.is_file()}
for row in rows:
 subprocess.run([sys.executable,'-B','.agents/skills/bio-thesis-formatter/scripts/bio_thesis.py','init','--template',str(Path('inputs')/row['template']),'--output',str(Path('output')/row['output']),'--review-stage','blind','--title-en',row['title_en'],'--major',row['major'],'--author',row['author'],'--student-id',row['student_id']],check=True)
assert before=={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in Path('inputs').iterdir() if p.is_file()}
print('Input hashes unchanged.')
'@ | python -B -"
